export const AUTO_DETECT_CODE = 'AUTO';
export const CUSTOM_EPSG_CODE = 'CUSTOM';

export const ALL_OPTIONS = [
  { code: AUTO_DETECT_CODE, label: 'AUTO — Auto-detect from coordinates', group: 'Special' },
  { code: CUSTOM_EPSG_CODE, label: 'CUSTOM — Enter any EPSG code...', group: 'Special' },
  ...PROJECTIONS,
];

/**
 * Fetch a proj4 string for any EPSG code from epsg.io at runtime.
 * Used for custom codes not in the static list.
 */
export async function fetchProj4FromEpsgIo(epsgCode) {
  const code = String(epsgCode).replace(/^EPSG:/i, '');
  try {
    const res = await fetch(`https://epsg.io/${code}.proj4`);
    if (!res.ok) return null;
    const text = (await res.text()).trim();
    if (!text || text.startsWith('<')) return null;
    return text;
  } catch {
    return null;
  }
}

/**
 * Auto-detect projection from sample coordinates.
 * Only reliable for WGS84 degree range.
 */
export function detectProjection(x, y) {
  if (x >= -180 && x <= 180 && y >= -90 && y <= 90) {
    return PROJECTIONS.find(p => p.code === 'EPSG:4326') || null;
  }
  return null;
}

/**
 * validateCoords — bounds removed; kept for App.jsx compatibility.
 */
export function validateCoords(x, y, epsgCode, swapXY) {
  if (x == null || y == null || !epsgCode) {
    return { ok: false, message: 'Missing coordinates or projection.' };
  }
  return { ok: true, message: 'Coordinates accepted.' };
}

/**
 * Convert [x, y] from proj4def to WGS84 [lng, lat].
 */
export function toWgs84(proj4lib, proj4def, x, y) {
  if (!proj4def) return [x, y];
  return proj4lib(proj4def, 'WGS84', [x, y]);
}
